#include "stem_core.hpp"
#include <fstream>
#include <iostream>
void require(bool b,const char* message){if(!b)throw std::runtime_error(message);}
int main(int argc,char** argv){try{require(argc==3,"asset_fit_test source.bin prepared.json");std::ifstream in(argv[1],std::ios::binary);unsigned h[4];in.read(reinterpret_cast<char*>(h),sizeof(h));require(h[0]==0x53544c32u&&h[1]<=1000000&&h[2]<=2000000,"Source admission");std::vector<std::array<float,3>> xyz(h[1]);std::vector<std::array<unsigned,3>> faces(h[2]);std::vector<unsigned> materials(h[2]),labels(h[1]);in.read(reinterpret_cast<char*>(xyz.data()),h[1]*12);in.read(reinterpret_cast<char*>(faces.data()),h[2]*12);in.read(reinterpret_cast<char*>(materials.data()),h[2]*4);in.read(reinterpret_cast<char*>(labels.data()),h[1]*4);require(bool(in),"Source read");std::vector<stem::Vec> points;for(auto p:xyz)points.push_back({p[0],p[2],-p[1]});std::ifstream meta(argv[2]);stem::Json j;meta>>j;auto prepared=stem::prepare(j,points,faces,labels);
    auto rejects=[&](stem::Json bad){bool rejected=false;try{stem::prepare(bad,points,faces,labels);}catch(...){rejected=true;}require(rejected,"Invalid forest admitted");};auto bad=j;bad["guide_order"][1]=bad["guide_order"][0];rejects(bad);bad=j;bad["guides"][0]["parent"]=0;rejects(bad);bad=j;bad["guides"][0]["unresolved"]=true;rejects(bad);
    auto rest=stem::restPose(*prepared);double error=0;for(unsigned i=0;i<points.size();++i){auto p=stem::point(*prepared,rest,i);error=std::max(error,std::hypot(p.x-points[i].x,p.y-points[i].y,p.z-points[i].z));}require(error<1e-7,"Rest reconstruction");
    unsigned roots=0;for(const auto& g:prepared->guides)if(g.parent<0){++roots;require(!g.anchors.empty(),"Basal root ring not pinned");}require(roots==3,"Lavender 01 independent roots changed");
    unsigned generation=2,activeCases=0;for(double x:{.8,.6,.5,.45,.4,.35,.3,.7}){stem::Vec centre{x,.52,-.096};auto result=stem::solve(*prepared,centre,.12,.001,.5,generation++);std::cout<<"x "<<x<<" ok "<<result.ok<<" "<<result.metrics.dump()<<" "<<result.error<<'\n';require(result.ok,"Lavender 01 sphere sweep rejected");auto roundTrip=stem::loadPose(*prepared,stem::savePose(result.pose));require(stem::savePose(roundTrip)==stem::savePose(result.pose),"Forest pose round trip");if(result.metrics.value("active_stems",0)>0){++activeCases;auto audit=stem::audit(*prepared,result.pose,centre,.12,.01);std::cout<<"AUDIT "<<audit.dump()<<'\n';require(audit.at("min_gap_m").get<double>()>=.001,"Delivered sphere clearance");require(audit.at("root_ring_error_m").get<double>()<1e-6,"Independent root moved");require(audit.at("rigid_part_edges_over_10pct")==0,"Rigid foliage stretched");}}
    require(activeCases>=3,"No meaningful collider contact cases");std::cout<<"PASS independent root pins, rest mesh, invalid forests, live fit and full float mesh checks\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
